);

CREATE TABLE daily_sales (
  order_date DATE PRIMARY KEY,
  total_amount DECIMAL(12, 2)
);

content.expectedQuery:
SELECT order_date,
       SUM(total_amount) OVER (
         ORDER BY order_date
         ROWS BETWEEN 2 PRECEDING AND CURRENT ROW
       ) AS rolling_total
FROM daily_sales;

